//! Devices on the local network, found without a driver, raw sockets, packet capture or admin:
//! an ICMP sweep of this PC's subnet (it fills Windows' neighbor table), the neighbor table itself
//! (`GetIpNetTable2`: IP ↔ MAC), mDNS / DNS-SD and SSDP / UPnP queries, reverse DNS, and the IEEE
//! OUI registry (`data/oui.tsv`, regenerated by `tools/oui.py`) for the vendor.
//!
//! Everything a device answers (names, banners, XML) is hostile input: parsed with hard bounds,
//! single-line, trimmed. UPnP descriptions are fetched only from the very IP that answered, inside
//! this PC's subnet, over plain HTTP with a short timeout (no redirects): a device cannot make the
//! app fetch anything else. The optional port check targets only devices from the last scan.

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::io::{Read, Write};
use std::net::{Ipv4Addr, SocketAddr, SocketAddrV4, TcpStream, UdpSocket};
use std::sync::Mutex;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::{Duration, Instant};

use serde::{Deserialize, Serialize};
use windows::Win32::NetworkManagement::IpHelper::{FreeMibTable, GetIpNetTable2, MIB_IPNET_TABLE2};
use windows::Win32::Networking::WinSock::{AF_INET, GetNameInfoW, NI_NAMEREQD, SOCKADDR, SOCKADDR_IN, socklen_t};

use crate::{dns, network, registry};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Kind {
    Router,
    ThisPc,
    Computer,
    Phone,
    Tv,
    Console,
    Printer,
    Camera,
    Speaker,
    Iot,
    Nas,
    Unknown,
}

#[derive(Debug, Clone, Serialize)]
pub struct Device {
    pub ip: String,
    pub mac: String,
    pub vendor: Option<String>,
    /// Locally administered (randomized) MAC: phones, tablets and Windows "random hardware address".
    pub private_mac: bool,
    pub hostname: Option<String>,
    /// Friendly name from UPnP or an mDNS instance ("Sala TV").
    pub name: Option<String>,
    pub manufacturer: Option<String>,
    pub model: Option<String>,
    pub kind: Kind,
    /// mDNS service types (`_googlecast._tcp`) and UPnP device types, short.
    pub services: Vec<String>,
    pub first_seen: u64,
    /// Not seen in any earlier scan (never on the very first scan).
    pub new: bool,
    pub known: bool,
}

#[derive(Debug, Clone, Serialize)]
pub struct Scan {
    pub subnet: String,
    pub swept: u32,
    pub elapsed_ms: u64,
    pub devices: Vec<Device>,
    pub new_count: usize,
    pub first_scan: bool,
}

#[derive(Debug, thiserror::Error)]
pub enum DeviceError {
    #[error("no_network")]
    NoNetwork,
    #[error("unknown_device")]
    UnknownDevice,
    #[error("io: {0}")]
    Io(#[from] std::io::Error),
}

/* ---------------- vendor (IEEE OUI) ---------------- */

static OUI: &str = include_str!("../data/oui.tsv");

fn oui_table() -> &'static [(u32, &'static str)] {
    static T: std::sync::OnceLock<Vec<(u32, &'static str)>> = std::sync::OnceLock::new();
    T.get_or_init(|| {
        OUI.lines()
            .filter_map(|l| {
                let (p, n) = l.split_once('\t')?;
                Some((u32::from_str_radix(p, 16).ok()?, n))
            })
            .collect()
    })
}

/// `aa:bb:cc:..` → the registered organisation (sorted table, binary search).
pub fn vendor(mac: &str) -> Option<&'static str> {
    let hex: String = mac.chars().filter(char::is_ascii_hexdigit).take(6).collect();
    let key = u32::from_str_radix(&hex, 16).ok().filter(|_| hex.len() == 6)?;
    let t = oui_table();
    t.binary_search_by_key(&key, |(p, _)| *p).ok().map(|i| t[i].1)
}

pub fn is_private_mac(mac: &str) -> bool {
    u8::from_str_radix(mac.get(..2).unwrap_or("00"), 16).is_ok_and(|b| b & 0x02 != 0)
}

/* ---------------- subnet ---------------- */

/// Hosts to sweep: the on-link network, or the /24 around this PC when the network is bigger
/// (a /16 would be 65k probes). Network, broadcast and this PC are left out.
pub fn sweep_targets(me: Ipv4Addr, prefix: u8) -> Vec<Ipv4Addr> {
    if !(8..=30).contains(&prefix) {
        return Vec::new();
    }
    let p = prefix.max(24);
    let mask = u32::MAX << (32 - u32::from(p));
    let net = u32::from(me) & mask;
    let bcast = net | !mask;
    ((net + 1)..bcast).map(Ipv4Addr::from).filter(|ip| *ip != me).collect()
}

fn in_subnet(ip: Ipv4Addr, me: Ipv4Addr, prefix: u8) -> bool {
    let p = u32::from(prefix.clamp(8, 32));
    let mask = u32::MAX.checked_shl(32 - p).unwrap_or(0);
    u32::from(ip) & mask == u32::from(me) & mask
}

/* ---------------- text from devices (hostile) ---------------- */

/// One line, printable, bounded.
pub fn clean(s: &str, max: usize) -> Option<String> {
    let t: String = s.chars().map(|c| if c.is_control() { ' ' } else { c }).collect();
    let t = t.split_whitespace().collect::<Vec<_>>().join(" ");
    let t: String = t.chars().take(max).collect();
    (!t.is_empty()).then_some(t)
}

/* ---------------- mDNS / DNS-SD ---------------- */

/// A DNS name at `pos` (with compression pointers), and the offset after it.
fn read_name(buf: &[u8], mut pos: usize) -> Option<(String, usize)> {
    let mut labels: Vec<String> = Vec::new();
    let mut end = None;
    for _ in 0..32 {
        let len = *buf.get(pos)? as usize;
        if len == 0 {
            end.get_or_insert(pos + 1);
            return Some((labels.join("."), end?));
        }
        if len & 0xC0 == 0xC0 {
            let ptr = ((len & 0x3F) << 8) | *buf.get(pos + 1)? as usize;
            end.get_or_insert(pos + 2);
            if ptr >= pos {
                return None; // only backwards pointers: no loops
            }
            pos = ptr;
            continue;
        }
        let label = buf.get(pos + 1..pos + 1 + len)?;
        labels.push(String::from_utf8_lossy(label).into_owned());
        pos += 1 + len;
    }
    None
}

#[derive(Debug, Default, PartialEq)]
struct Dns {
    /// PTR: owner name → target name.
    ptr: Vec<(String, String)>,
    /// A: name → address.
    a: Vec<(String, Ipv4Addr)>,
}

fn parse_dns(buf: &[u8]) -> Option<Dns> {
    if buf.len() < 12 {
        return None;
    }
    let count = |i: usize| u16::from_be_bytes([buf[i], buf[i + 1]]) as usize;
    let (qd, records) = (count(4), count(6) + count(8) + count(10));
    if qd > 32 || records > 256 {
        return None;
    }
    let mut pos = 12;
    for _ in 0..qd {
        pos = read_name(buf, pos)?.1 + 4;
    }
    let mut out = Dns::default();
    for _ in 0..records {
        let (owner, p) = read_name(buf, pos)?;
        let h = buf.get(p..p + 10)?;
        let rtype = u16::from_be_bytes([h[0], h[1]]);
        let rdlen = u16::from_be_bytes([h[8], h[9]]) as usize;
        let rdata = p + 10;
        buf.get(rdata..rdata + rdlen)?;
        match rtype {
            12 => out.ptr.push((owner, read_name(buf, rdata)?.0)),
            1 if rdlen == 4 => out.a.push((owner, Ipv4Addr::new(buf[rdata], buf[rdata + 1], buf[rdata + 2], buf[rdata + 3]))),
            _ => {}
        }
        pos = rdata + rdlen;
    }
    Some(out)
}

/// A query for `names` (PTR, "unicast response" bit set so answers come straight to us).
fn mdns_query(names: &[String]) -> Vec<u8> {
    let mut q = vec![0, 0, 0, 0, 0, names.len() as u8, 0, 0, 0, 0, 0, 0];
    q[4] = (names.len() >> 8) as u8;
    for n in names {
        for label in n.split('.').filter(|l| !l.is_empty()) {
            let l = &label.as_bytes()[..label.len().min(63)];
            q.push(l.len() as u8);
            q.extend_from_slice(l);
        }
        q.extend_from_slice(&[0, 0, 12, 0x80, 1]);
    }
    q
}

#[derive(Debug, Default)]
struct Mdns {
    services: HashMap<Ipv4Addr, BTreeSet<String>>,
    instance: HashMap<Ipv4Addr, String>,
    host: HashMap<Ipv4Addr, String>,
}

/// Service types whose instance name is what the owner called the device ("Sala TV").
const FRIENDLY: &[&str] = &[
    "_googlecast", "_airplay", "_raop", "_spotify-connect", "_ipp", "_printer", "_pdl-datastream", "_hap", "_smb",
    "_workstation", "_companion-link", "_device-info", "_sonos", "_amzn-wplay", "_androidtvremote",
];

/// Apps register random ids as service types (`_fc9f5ed42c8a._tcp`): noise for a device list.
fn random_service(t: &str) -> bool {
    let first = t.split('.').next().unwrap_or("").trim_start_matches('_');
    first.len() >= 8 && first.chars().all(|c| c.is_ascii_hexdigit())
}

fn mdns_round(sock: &UdpSocket, names: &[String], wait: Duration, out: &mut Mdns, types: &mut BTreeSet<String>) {
    let dst = SocketAddr::from((Ipv4Addr::new(224, 0, 0, 251), 5353));
    let _ = sock.send_to(&mdns_query(names), dst);
    let deadline = Instant::now() + wait;
    let mut buf = [0u8; 9000];
    while let Some(left) = deadline.checked_duration_since(Instant::now()) {
        let _ = sock.set_read_timeout(Some(left.max(Duration::from_millis(10))));
        let Ok((n, SocketAddr::V4(from))) = sock.recv_from(&mut buf) else {
            break;
        };
        let Some(d) = parse_dns(&buf[..n]) else {
            continue;
        };
        let ip = *from.ip();
        for (owner, target) in &d.ptr {
            if owner.eq_ignore_ascii_case("_services._dns-sd._udp.local") {
                if types.len() < 40 {
                    types.insert(target.to_ascii_lowercase());
                }
                continue;
            }
            // `<instance>.<_type>._tcp.local` → instance name and the service type.
            let t = owner.trim_end_matches(".local").to_ascii_lowercase();
            if random_service(&t) {
                continue;
            }
            let svc = out.services.entry(ip).or_default();
            if svc.len() < 16 {
                svc.insert(t.clone());
            }
            // Only well-known services carry a human name in the instance label.
            if FRIENDLY.iter().any(|f| t.starts_with(f))
                && let Some(inst) = target.strip_suffix(&format!(".{owner}"))
                && let Some(name) = clean(inst, 48)
            {
                out.instance.entry(ip).or_insert(name);
            }
        }
        for (name, addr) in &d.a {
            if *addr == ip
                && let Some(h) = clean(name.trim_end_matches(".local"), 48)
            {
                out.host.entry(ip).or_insert(h);
            }
        }
    }
}

fn mdns(me: Ipv4Addr) -> Mdns {
    let mut out = Mdns::default();
    let Ok(sock) = UdpSocket::bind(SocketAddrV4::new(me, 0)) else {
        return out;
    };
    let _ = sock.set_multicast_ttl_v4(1);
    let mut types = BTreeSet::new();
    mdns_round(&sock, &["_services._dns-sd._udp.local".into()], Duration::from_millis(1200), &mut out, &mut types);
    if !types.is_empty() {
        let names: Vec<String> = types.into_iter().collect();
        for chunk in names.chunks(12) {
            mdns_round(&sock, chunk, Duration::from_millis(900), &mut out, &mut BTreeSet::new());
        }
    }
    out
}

/* ---------------- SSDP / UPnP ---------------- */

#[derive(Debug, Default, Clone)]
struct Upnp {
    server: Option<String>,
    location: Option<String>,
    types: BTreeSet<String>,
    friendly: Option<String>,
    manufacturer: Option<String>,
    model: Option<String>,
}

fn header<'a>(resp: &'a str, name: &str) -> Option<&'a str> {
    resp.lines().find_map(|l| {
        let (k, v) = l.split_once(':')?;
        k.trim().eq_ignore_ascii_case(name).then(|| v.trim())
    })
}

/// `urn:schemas-upnp-org:device:MediaRenderer:1` → `MediaRenderer`.
fn short_type(st: &str) -> Option<String> {
    let mut parts = st.split(':');
    let kind = parts.clone().nth(2)?;
    (kind == "device" || kind == "service").then(|| parts.nth(3)).flatten().and_then(|t| clean(t, 40))
}

fn ssdp(me: Ipv4Addr) -> HashMap<Ipv4Addr, Upnp> {
    let mut out: HashMap<Ipv4Addr, Upnp> = HashMap::new();
    let Ok(sock) = UdpSocket::bind(SocketAddrV4::new(me, 0)) else {
        return out;
    };
    let _ = sock.set_multicast_ttl_v4(2);
    let msg = "M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: \"ssdp:discover\"\r\nMX: 1\r\nST: ssdp:all\r\n\r\n";
    let _ = sock.send_to(msg.as_bytes(), (Ipv4Addr::new(239, 255, 255, 250), 1900));
    let deadline = Instant::now() + Duration::from_millis(2000);
    let mut buf = [0u8; 4096];
    while let Some(left) = deadline.checked_duration_since(Instant::now()) {
        let _ = sock.set_read_timeout(Some(left.max(Duration::from_millis(10))));
        let Ok((n, SocketAddr::V4(from))) = sock.recv_from(&mut buf) else {
            break;
        };
        let text = String::from_utf8_lossy(&buf[..n]);
        let e = out.entry(*from.ip()).or_default();
        if e.server.is_none() {
            e.server = header(&text, "server").and_then(|s| clean(s, 80));
        }
        if e.location.is_none() {
            e.location = header(&text, "location").map(str::to_string);
        }
        if let Some(t) = header(&text, "st").and_then(short_type)
            && e.types.len() < 12
        {
            e.types.insert(t);
        }
    }
    out
}

/// `http://<ip>:<port>/path` only when `<ip>` is the device that answered (no SSRF to elsewhere).
fn location_target(loc: &str, device: Ipv4Addr) -> Option<(SocketAddr, String)> {
    let rest = loc.strip_prefix("http://")?;
    let (hostport, path) = rest.split_once('/').map_or((rest, ""), |(h, p)| (h, p));
    let (host, port) = hostport.split_once(':').map_or((hostport, "80"), |(h, p)| (h, p));
    let ip: Ipv4Addr = host.parse().ok()?;
    let port: u16 = port.parse().ok().filter(|p| *p > 0)?;
    let path_ok = path.len() <= 200 && path.chars().all(|c| c.is_ascii_graphic());
    (ip == device && path_ok).then(|| (SocketAddr::from((ip, port)), format!("/{path}")))
}

fn xml_tag(xml: &str, tag: &str) -> Option<String> {
    let start = xml.find(&format!("<{tag}>"))? + tag.len() + 2;
    let end = start + xml.get(start..)?.find(&format!("</{tag}>"))?;
    let raw = xml.get(start..end)?;
    let decoded = raw.replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"").replace("&apos;", "'");
    clean(&decoded, 64)
}

fn describe(u: &mut Upnp, device: Ipv4Addr) {
    let Some((addr, path)) = u.location.as_deref().and_then(|l| location_target(l, device)) else {
        return;
    };
    let Ok(mut s) = TcpStream::connect_timeout(&addr, Duration::from_millis(800)) else {
        return;
    };
    let _ = s.set_read_timeout(Some(Duration::from_millis(1200)));
    let _ = s.set_write_timeout(Some(Duration::from_millis(800)));
    let req = format!("GET {path} HTTP/1.0\r\nHost: {addr}\r\nConnection: close\r\n\r\n");
    if s.write_all(req.as_bytes()).is_err() {
        return;
    }
    let mut body = Vec::new();
    let _ = s.take(64 * 1024).read_to_end(&mut body);
    let xml = String::from_utf8_lossy(&body);
    u.friendly = xml_tag(&xml, "friendlyName");
    u.manufacturer = xml_tag(&xml, "manufacturer");
    u.model = xml_tag(&xml, "modelName");
    if let Some(t) = xml_tag(&xml, "deviceType").and_then(|t| short_type(&t)) {
        u.types.insert(t);
    }
}

/* ---------------- neighbors, names ---------------- */

/// (ip, mac) pairs Windows resolved on this interface.
fn neighbors(if_index: u32) -> Vec<(Ipv4Addr, String)> {
    let mut out = Vec::new();
    let mut table: *mut MIB_IPNET_TABLE2 = std::ptr::null_mut();
    // SAFETY: the API allocates the table; freed with FreeMibTable below.
    unsafe {
        if GetIpNetTable2(AF_INET, &mut table).is_err() || table.is_null() {
            return out;
        }
        let t = &*table;
        let rows = std::slice::from_raw_parts(t.Table.as_ptr(), t.NumEntries as usize);
        for r in rows {
            // 2 Probe, 3 Delay, 4 Stale, 5 Reachable, 6 Permanent.
            if r.InterfaceIndex != if_index || r.State.0 < 2 || r.PhysicalAddressLength != 6 {
                continue;
            }
            let mac = &r.PhysicalAddress[..6];
            if mac.iter().all(|b| *b == 0) || mac.iter().all(|b| *b == 0xFF) || mac[0] & 1 == 1 {
                continue;
            }
            if r.Address.si_family != AF_INET {
                continue;
            }
            let ip = Ipv4Addr::from(u32::from_be(r.Address.Ipv4.sin_addr.S_un.S_addr));
            out.push((ip, mac.iter().map(|b| format!("{b:02x}")).collect::<Vec<_>>().join(":")));
        }
        FreeMibTable(table.cast());
    }
    out
}

fn reverse_dns(ip: Ipv4Addr) -> Option<String> {
    let sa = SOCKADDR_IN { sin_family: AF_INET, sin_addr: ip.into(), ..Default::default() };
    let mut host = [0u16; 256];
    // SAFETY: valid SOCKADDR_IN and output buffer; NI_NAMEREQD = fail instead of echoing the IP.
    let rc = unsafe {
        GetNameInfoW(
            (&raw const sa).cast::<SOCKADDR>(),
            socklen_t(std::mem::size_of::<SOCKADDR_IN>() as i32),
            Some(&mut host),
            None,
            NI_NAMEREQD as i32,
        )
    };
    if rc != 0 {
        return None;
    }
    let end = host.iter().position(|&c| c == 0).unwrap_or(host.len());
    clean(String::from_utf16_lossy(&host[..end]).trim_end_matches('.'), 64)
}

/// Run `f` over `items` with `workers` threads, returning what finished before `deadline`.
fn parallel<T: Send + Sync, R: Send + 'static>(items: &[T], workers: usize, f: impl Fn(&T) -> R + Sync) -> Vec<R> {
    let next = AtomicUsize::new(0);
    let out = Mutex::new(Vec::new());
    std::thread::scope(|s| {
        for _ in 0..workers.min(items.len()).max(1) {
            s.spawn(|| {
                while let Some(item) = items.get(next.fetch_add(1, Ordering::Relaxed)) {
                    let r = f(item);
                    out.lock().unwrap().push(r);
                }
            });
        }
    });
    out.into_inner().unwrap()
}

/* ---------------- classification ---------------- */

fn has(hay: &str, needles: &[&str]) -> bool {
    needles.iter().any(|n| hay.contains(n))
}

/// Ordered guess: role, services, UPnP, hostname, vendor, private MAC.
pub fn classify(d: &Device, router: bool, this_pc: bool) -> Kind {
    if this_pc {
        return Kind::ThisPc;
    }
    if router {
        return Kind::Router;
    }
    let svc = d.services.join(" ").to_ascii_lowercase();
    let host = d.hostname.as_deref().unwrap_or("").to_ascii_lowercase();
    let name = d.name.as_deref().unwrap_or("").to_ascii_lowercase();
    let model = format!("{} {}", d.manufacturer.as_deref().unwrap_or(""), d.model.as_deref().unwrap_or("")).to_ascii_lowercase();
    let vendor = d.vendor.as_deref().unwrap_or("").to_ascii_lowercase();
    let text = format!("{host} {name} {model}");

    if has(&svc, &["_ipp", "_printer", "_pdl-datastream", "_scanner", "printer"]) {
        return Kind::Printer;
    }
    if has(&svc, &["_googlecast", "_androidtvremote", "_amzn-wplay", "mediarenderer", "dial", "_viziocast", "_roku"])
        || has(&text, &["tv", "chromecast", "roku", "fire tv", "bravia", "smart tv", "webos"])
    {
        return Kind::Tv;
    }
    if has(&svc, &["_spotify-connect", "_sonos", "_raop"]) || has(&text, &["echo", "nest mini", "homepod", "soundbar", "speaker"]) {
        return Kind::Speaker;
    }
    if has(&text, &["xbox", "playstation", "ps5", "ps4", "nintendo", "switch"]) || has(&vendor, &["nintendo", "sony interactive"]) {
        return Kind::Console;
    }
    if has(&svc, &["_rtsp", "_onvif"]) || has(&text, &["camera", "cam ", "ipc", "doorbell"]) || has(&vendor, &["hikvision", "dahua", "reolink", "ezviz", "wyze"]) {
        return Kind::Camera;
    }
    if has(&vendor, &["synology", "qnap", "western digital", "buffalo"]) || has(&text, &["nas", "diskstation"]) {
        return Kind::Nas;
    }
    if has(&svc, &["_hap", "_homekit", "_matter", "_miio", "_tuya", "_shelly", "_esphome"])
        || has(&vendor, &["espressif", "tuya", "shelly", "itead", "broadlink", "lifx", "signify", "philips lighting", "sonoff"])
    {
        return Kind::Iot;
    }
    if has(&svc, &["_companion-link", "_apple-mobdev", "_rdlink"]) || has(&host, &["iphone", "ipad", "android", "galaxy", "redmi", "poco", "moto", "pixel", "xiaomi"]) {
        return Kind::Phone;
    }
    if has(&svc, &["_smb", "_workstation", "_rfb", "_ssh", "_device-info", "_nvstream", "_sftp"])
        || has(&host, &["desktop-", "laptop-", "pc-", "macbook", "imac", "notebook"])
        || has(&vendor, &["raspberry pi"])
    {
        return Kind::Computer;
    }
    if has(&svc, &["internetgatewaydevice", "wanipconnection"]) {
        return Kind::Router;
    }
    if d.private_mac {
        return Kind::Phone; // randomized MACs are mostly phones and tablets
    }
    Kind::Unknown
}

/* ---------------- history ---------------- */

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct Seen {
    first_seen: u64,
    last_seen: u64,
    #[serde(default)]
    known: bool,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct History {
    scans: u32,
    devices: BTreeMap<String, Seen>,
}

fn history_file() -> std::path::PathBuf {
    registry::data_dir().join("devices.json")
}

fn load_history() -> History {
    std::fs::read_to_string(history_file())
        .ok()
        .and_then(|t| serde_json::from_str::<History>(&t).ok())
        .map(|mut h| {
            // Hostile file: only well-formed MAC keys survive.
            h.devices.retain(|mac, _| valid_mac(mac));
            h
        })
        .unwrap_or_default()
}

fn save_history(h: &History) -> Result<(), DeviceError> {
    let f = history_file();
    if let Some(d) = f.parent() {
        std::fs::create_dir_all(d)?;
    }
    std::fs::write(f, serde_json::to_string_pretty(h).unwrap_or_default())?;
    Ok(())
}

pub fn valid_mac(mac: &str) -> bool {
    mac.len() == 17 && mac.split(':').all(|p| p.len() == 2 && p.chars().all(|c| c.is_ascii_hexdigit()))
}

/// Mark a device as known (the "new" badge goes away) or not.
pub fn set_known(mac: &str, known: bool) -> Result<(), DeviceError> {
    let mac = mac.to_ascii_lowercase();
    if !valid_mac(&mac) {
        return Err(DeviceError::UnknownDevice);
    }
    let mut h = load_history();
    let e = h.devices.get_mut(&mac).ok_or(DeviceError::UnknownDevice)?;
    e.known = known;
    save_history(&h)
}

/* ---------------- scan ---------------- */

/// IPs of the last scan: the port check only targets these.
static LAST: Mutex<Vec<Ipv4Addr>> = Mutex::new(Vec::new());

pub fn scan() -> Result<Scan, DeviceError> {
    let t0 = Instant::now();
    let adapter = dns::adapters().into_iter().find(|a| a.primary && a.ipv4.is_some()).ok_or(DeviceError::NoNetwork)?;
    let me = adapter.ipv4.ok_or(DeviceError::NoNetwork)?;
    let targets = sweep_targets(me, adapter.prefix);

    // Sweep, mDNS and SSDP at the same time (~2.5 s).
    let (mdns_found, mut upnp) = std::thread::scope(|s| {
        let m = s.spawn(|| mdns(me));
        let u = s.spawn(|| ssdp(me));
        parallel(&targets, 64, |ip| network::ping(*ip, 400).ok());
        (m.join().unwrap_or_default(), u.join().unwrap_or_default())
    });

    let mut found: BTreeMap<Ipv4Addr, String> = neighbors(adapter.if_index)
        .into_iter()
        .filter(|(ip, _)| in_subnet(*ip, me, adapter.prefix) && *ip != me)
        .collect();
    if let Some(mac) = &adapter.mac {
        found.insert(me, mac.clone());
    }
    found.truncate_to(512);

    // Names: reverse DNS and UPnP descriptions, in parallel, bounded.
    let ips: Vec<Ipv4Addr> = found.keys().copied().collect();
    let hostnames: HashMap<Ipv4Addr, String> =
        parallel(&ips, 32, |ip| reverse_dns(*ip).map(|h| (*ip, h))).into_iter().flatten().collect();
    let upnp_ips: Vec<Ipv4Addr> = upnp.keys().copied().filter(|ip| found.contains_key(ip)).take(24).collect();
    let described: Vec<(Ipv4Addr, Upnp)> = parallel(&upnp_ips, 12, |ip| {
        let mut u = upnp.get(ip).cloned().unwrap_or_default();
        describe(&mut u, *ip);
        (*ip, u)
    });
    for (ip, u) in described {
        upnp.insert(ip, u);
    }

    let mut hist = load_history();
    let first_scan = hist.scans == 0;
    let now = registry::now_unix();
    let mut devices = Vec::new();
    for (ip, mac) in &found {
        let u = upnp.get(ip);
        let mut services: Vec<String> = mdns_found.services.get(ip).map(|s| s.iter().cloned().collect()).unwrap_or_default();
        if let Some(u) = u {
            services.extend(u.types.iter().cloned());
        }
        services.truncate(16);
        let seen = hist.devices.entry(mac.clone()).or_insert(Seen { first_seen: now, last_seen: now, known: false });
        let is_new = !first_scan && seen.first_seen == now && !seen.known;
        seen.last_seen = now;
        let mut d = Device {
            ip: ip.to_string(),
            mac: mac.clone(),
            vendor: vendor(mac).map(str::to_string),
            private_mac: is_private_mac(mac),
            hostname: hostnames.get(ip).cloned().or_else(|| mdns_found.host.get(ip).cloned()),
            name: u.and_then(|u| u.friendly.clone()).or_else(|| mdns_found.instance.get(ip).cloned()),
            manufacturer: u.and_then(|u| u.manufacturer.clone()),
            model: u.and_then(|u| u.model.clone()).or_else(|| u.and_then(|u| u.server.clone())),
            kind: Kind::Unknown,
            services,
            first_seen: seen.first_seen,
            new: is_new,
            known: seen.known,
        };
        d.kind = classify(&d, Some(*ip) == adapter.gateway, *ip == me);
        devices.push(d);
    }
    hist.scans = hist.scans.saturating_add(1);
    if hist.devices.len() > 500 {
        let mut by_age: Vec<(String, u64)> = hist.devices.iter().map(|(m, s)| (m.clone(), s.last_seen)).collect();
        by_age.sort_by_key(|(_, t)| *t);
        for (m, _) in by_age.into_iter().take(hist.devices.len() - 500) {
            hist.devices.remove(&m);
        }
    }
    save_history(&hist)?;
    *LAST.lock().unwrap() = found.keys().copied().collect();

    devices.sort_by_key(|d| (d.kind != Kind::Router, d.kind != Kind::ThisPc, !d.new, d.ip.parse::<Ipv4Addr>().map(u32::from).unwrap_or(0)));
    let new_count = devices.iter().filter(|d| d.new).count();
    let net = Ipv4Addr::from(u32::from(me) & (u32::MAX << (32 - u32::from(adapter.prefix.clamp(8, 32).max(24)))));
    Ok(Scan {
        subnet: format!("{net}/{}", adapter.prefix.max(24)),
        swept: targets.len() as u32,
        elapsed_ms: t0.elapsed().as_millis() as u64,
        devices,
        new_count,
        first_scan,
    })
}

trait Truncate {
    fn truncate_to(&mut self, n: usize);
}
impl<K: Ord + Clone, V> Truncate for BTreeMap<K, V> {
    fn truncate_to(&mut self, n: usize) {
        while self.len() > n {
            let Some(k) = self.keys().next_back().cloned() else { break };
            self.remove(&k);
        }
    }
}

/* ---------------- port check (opt-in) ---------------- */

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Risk {
    High,
    Medium,
    Info,
}

/// Services worth knowing about on a home network (niv-on's risky list + common admin ports).
pub const PORTS: &[(u16, &str, Risk)] = &[
    (21, "ftp", Risk::Medium),
    (22, "ssh", Risk::Info),
    (23, "telnet", Risk::High),
    (80, "http", Risk::Info),
    (139, "netbios", Risk::Info),
    (445, "smb", Risk::Medium),
    (554, "rtsp", Risk::Medium),
    (1883, "mqtt", Risk::Medium),
    (2323, "telnet", Risk::High),
    (3389, "rdp", Risk::Medium),
    (5555, "adb", Risk::High),
    (5900, "vnc", Risk::Medium),
    (7547, "tr069", Risk::Medium),
    (8080, "http", Risk::Info),
    (8443, "https", Risk::Info),
    (9100, "printer", Risk::Info),
];

#[derive(Debug, Clone, Serialize)]
pub struct OpenPort {
    pub port: u16,
    pub service: &'static str,
    pub risk: Risk,
}

/// TCP connect to [`PORTS`] on one device from the last scan (never an arbitrary address).
pub fn check_ports(ip: &str) -> Result<Vec<OpenPort>, DeviceError> {
    let ip: Ipv4Addr = ip.parse().map_err(|_| DeviceError::UnknownDevice)?;
    if !LAST.lock().unwrap().contains(&ip) {
        return Err(DeviceError::UnknownDevice);
    }
    let mut open: Vec<OpenPort> = parallel(PORTS, 16, |(port, service, risk)| {
        TcpStream::connect_timeout(&SocketAddr::from((ip, *port)), Duration::from_millis(600))
            .ok()
            .map(|_| OpenPort { port: *port, service, risk: *risk })
    })
    .into_iter()
    .flatten()
    .collect();
    open.sort_by_key(|p| p.port);
    Ok(open)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn oui_and_macs() {
        assert_eq!(vendor("b8:27:eb:12:34:56"), Some("Raspberry Pi Foundation"));
        assert_eq!(vendor("24-A1-60-00-00-00"), Some("Espressif"));
        assert_eq!(vendor("zz"), None);
        assert!(is_private_mac("da:a1:19:00:00:01") && !is_private_mac("b8:27:eb:00:00:01"));
        assert!(valid_mac("aa:bb:cc:dd:ee:ff") && !valid_mac("aa:bb:cc:dd:ee") && !valid_mac("../../x"));
        assert!(oui_table().windows(2).all(|w| w[0].0 < w[1].0), "sorted for binary search");
    }

    #[test]
    fn subnet_math() {
        let me = Ipv4Addr::new(192, 168, 0, 10);
        let t = sweep_targets(me, 24);
        assert_eq!(t.len(), 253);
        assert!(!t.contains(&me) && !t.contains(&Ipv4Addr::new(192, 168, 0, 255)) && !t.contains(&Ipv4Addr::new(192, 168, 0, 0)));
        assert_eq!(sweep_targets(Ipv4Addr::new(10, 1, 2, 3), 16).len(), 253, "big networks: only the /24 around us");
        assert_eq!(sweep_targets(me, 30).len(), 1);
        assert!(sweep_targets(me, 32).is_empty());
        assert!(in_subnet(Ipv4Addr::new(192, 168, 0, 200), me, 24) && !in_subnet(Ipv4Addr::new(192, 168, 1, 1), me, 24));
    }

    #[test]
    fn dns_parser_is_bounded() {
        // Response: 1 PTR `_googlecast._tcp.local` → `Sala._googlecast._tcp.local` (compressed) + 1 A.
        let mut p = vec![0, 0, 0x84, 0, 0, 0, 0, 2, 0, 0, 0, 0];
        let owner = p.len();
        for l in ["_googlecast", "_tcp", "local"] {
            p.push(l.len() as u8);
            p.extend_from_slice(l.as_bytes());
        }
        p.push(0);
        p.extend_from_slice(&[0, 12, 0, 1, 0, 0, 0, 120, 0, 7, 4]);
        p.extend_from_slice(b"Sala");
        p.extend_from_slice(&[0xC0, owner as u8]);
        p.extend_from_slice(&[5]);
        p.extend_from_slice(b"tvbox");
        p.extend_from_slice(&[5]);
        p.extend_from_slice(b"local");
        p.push(0);
        p.extend_from_slice(&[0, 1, 0, 1, 0, 0, 0, 120, 0, 4, 192, 168, 0, 50]);
        let d = parse_dns(&p).expect("parses");
        assert_eq!(d.ptr, vec![("_googlecast._tcp.local".into(), "Sala._googlecast._tcp.local".into())]);
        assert_eq!(d.a, vec![("tvbox.local".into(), Ipv4Addr::new(192, 168, 0, 50))]);
        // Truncated, looping pointer, absurd counts: refused, no panic.
        assert!(parse_dns(&p[..20]).is_none());
        assert!(read_name(&[0xC0, 0x00], 0).is_none());
        assert!(parse_dns(&[0, 0, 0, 0, 0xFF, 0xFF, 0, 0, 0, 0, 0, 0]).is_none());
        for cut in 0..p.len() {
            let _ = parse_dns(&p[..cut]);
        }
    }

    #[test]
    fn upnp_location_cannot_point_elsewhere() {
        let dev = Ipv4Addr::new(192, 168, 0, 20);
        assert!(location_target("http://192.168.0.20:49152/desc.xml", dev).is_some());
        assert!(location_target("http://192.168.0.21:49152/desc.xml", dev).is_none(), "other host");
        assert!(location_target("http://evil.example/desc.xml", dev).is_none(), "names");
        assert!(location_target("https://192.168.0.20/x", dev).is_none(), "only http");
        assert!(location_target("http://192.168.0.20:0/x", dev).is_none());
        assert!(location_target("http://192.168.0.20/a b", dev).is_none());
        assert_eq!(xml_tag("<root><friendlyName>Sala &amp; TV\n</friendlyName></root>", "friendlyName").as_deref(), Some("Sala & TV"));
        assert_eq!(short_type("urn:schemas-upnp-org:device:MediaRenderer:1").as_deref(), Some("MediaRenderer"));
        assert_eq!(clean("a\u{0}b\r\nc", 10).as_deref(), Some("a b c"));
        assert!(random_service("_fc9f5ed42c8a._tcp") && !random_service("_googlecast._tcp"));
    }

    #[test]
    fn classification_order() {
        let base = Device {
            ip: "192.168.0.5".into(),
            mac: "b8:27:eb:00:00:01".into(),
            vendor: None,
            private_mac: false,
            hostname: None,
            name: None,
            manufacturer: None,
            model: None,
            kind: Kind::Unknown,
            services: vec![],
            first_seen: 0,
            new: false,
            known: false,
        };
        let with = |f: &dyn Fn(&mut Device)| {
            let mut d = base.clone();
            f(&mut d);
            classify(&d, false, false)
        };
        assert_eq!(classify(&base, true, false), Kind::Router);
        assert_eq!(classify(&base, false, true), Kind::ThisPc);
        assert_eq!(with(&|d| d.services = vec!["_googlecast._tcp".into()]), Kind::Tv);
        assert_eq!(with(&|d| d.services = vec!["_ipp._tcp".into()]), Kind::Printer);
        assert_eq!(with(&|d| d.vendor = Some("Espressif".into())), Kind::Iot);
        assert_eq!(with(&|d| d.hostname = Some("DESKTOP-ABC".into())), Kind::Computer);
        assert_eq!(with(&|d| d.private_mac = true), Kind::Phone);
        assert_eq!(classify(&base, false, false), Kind::Unknown);
    }

    #[test]
    fn port_check_refuses_addresses_outside_the_last_scan() {
        assert!(matches!(check_ports("8.8.8.8"), Err(DeviceError::UnknownDevice)));
        assert!(matches!(check_ports("not an ip"), Err(DeviceError::UnknownDevice)));
    }

    /// Scans the real network: run by hand (`cargo test -- --ignored devices`).
    #[test]
    #[ignore]
    fn scans_this_network() {
        // SAFETY: same override every data-dir test in this crate uses (process-wide env var).
        unsafe { std::env::set_var("G2BOOST_DATA_DIR", crate::registry::tests::test_data_dir()) };
        let s = scan().expect("scan");
        println!("{} devices in {} ms on {}", s.devices.len(), s.elapsed_ms, s.subnet);
        for d in &s.devices {
            println!("{:?} {} {:?} {:?} {:?} {:?}", d.kind, d.ip, d.vendor, d.hostname, d.name, d.services);
        }
        assert!(s.devices.iter().any(|d| d.kind == Kind::ThisPc));
    }
}
